var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(UnityEditor.EditorApplication.isPlaying||scene.path!="Assets/Skybreak/Handbuilt/Scenes/SkybreakStoneFloor.unity")throw new System.InvalidOperationException("Open the map in Edit Mode.");
var p=UnityEngine.Object.FindFirstObjectByType<Skybreak.Descent.DescentCharacterController>();
var capsule=p.GetComponent<UnityEngine.CharacterController>();
UnityEditor.Undo.RecordObjects(new UnityEngine.Object[]{p,p.visual,capsule,p.viewCamera.transform},"Enlarge Arc and adjust camera");
p.visual.localScale=UnityEngine.Vector3.one*1.3f;
capsule.height=1.88f*1.3f;capsule.radius=.32f*1.3f;capsule.center=new UnityEngine.Vector3(0,.94f*1.3f,0);
p.cameraPivotHeight=2.08f;p.cameraShoulderOffset=.8f;p.cameraDistance=5f;p.hideBodyDistance=1.65f;
UnityEditor.PrefabUtility.RecordPrefabInstancePropertyModifications(p);
UnityEditor.PrefabUtility.RecordPrefabInstancePropertyModifications(p.visual);
UnityEditor.PrefabUtility.RecordPrefabInstancePropertyModifications(capsule);
UnityEngine.Physics.SyncTransforms();
var rotation=UnityEngine.Quaternion.Euler(10,0,0);
var pivot=p.transform.position+UnityEngine.Vector3.up*p.cameraPivotHeight;
var offset=rotation*new UnityEngine.Vector3(p.cameraShoulderOffset,0,-p.cameraDistance);
float distance=offset.magnitude;
if(UnityEngine.Physics.SphereCast(pivot,.22f,offset.normalized,out var hit,distance,p.environmentMask,UnityEngine.QueryTriggerInteraction.Ignore))distance=UnityEngine.Mathf.Max(.25f,hit.distance-.10f);
p.viewCamera.transform.SetPositionAndRotation(pivot+offset.normalized*distance,rotation);
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
if(!UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene))throw new System.IO.IOException("Could not save Arc size change.");
var report=new[]{"Visual scale: 1.3 (30 percent larger)","Root scale remains 1; only the visual and explicit capsule dimensions were resized.","Capsule height: "+capsule.height+"m / radius: "+capsule.radius+"m","Camera pivot: "+p.cameraPivotHeight+"m / distance: "+p.cameraDistance+"m / shoulder offset: "+p.cameraShoulderOffset+"m","Original Arc prefab and map geometry unchanged. Shared controller gained adjustable camera offsets, with its previous values as defaults."};
System.IO.File.WriteAllLines("Assets/Skybreak/Handbuilt/Reports/ArcSize.txt",report);
return string.Join("\n",report);
